using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private readonly ActorSkeletonPoseOperations _bones=new();private readonly ActorTextSettingsOperations _textSettings=new();private readonly ActorFontPickerOperations _fonts=new();
    public void add_skeleton_editor(Control owner,Resource actor)
    {
        var bones=actor.Get("values").AsGodotDictionary().GetValueOrDefault("rig_bones",new GArray()).AsGodotArray();var panel=section_page(owner,"Bone Pose","Properties");if(bones.Count==0){add_label(panel,"Import a rigged model to edit its bones.");return;}int selected=Math.Clamp(actor.GetMeta("editor_selected_bone",0).AsInt32(),0,bones.Count-1);var choose=new OptionButton{Name="RigBonePicker",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};foreach(var bone in bones)choose.AddItem(bone.AsGodotDictionary()["name"].AsString());choose.Select(selected);panel.AddChild(choose);choose.ItemSelected+=index=>{actor.SetMeta("editor_selected_bone",index);actor.SetMeta("editor_bone_mode",true);owner.CallDeferred("_rebuild_selected");};var model=Ui<RefCounted>(owner,"model");foreach(string channel in new[]{"position","rotation","scale"}){var heading=new HBoxContainer();panel.AddChild(heading);heading.AddChild(new Label{Text=channel.Capitalize(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var property=_properties.create("bone_"+channel,bones[selected].AsGodotDictionary()["name"].AsString()+" / "+channel.Capitalize(),channel=="scale"?Vector3.One:Vector3.Zero,true);add_keyframe_button(owner,heading,actor,property,_bones.path(selected,channel),default);for(int i=0;i<3;i++){int axis=i;var row=new HBoxContainer();panel.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis],Modulate=new Color(new[]{"ee9e9e","9ed8b5","99bce8"}[axis])});var input=number(owner,_bones.value(actor,selected,channel)[axis],.01);input.Name=$"Bone_{channel}_{axis}";row.AddChild(input);var before=new Settings();Vector3 Changed(double value){var next=_bones.value(actor,selected,channel);next[axis]=(float)value;return next;}input.Connect("interaction_started",Callable.From(()=>before=_bones.capture(model,actor)));input.Connect("preview_changed",Callable.From<double>(value=>_bones.preview(model,actor,selected,channel,Changed(value))));input.Connect("drag_committed",Callable.From<double>(value=>{_bones.commit(model,before.Count>0?before:_bones.capture(model,actor),selected,new Settings{[channel]=Changed(value)},false);before=new Settings();}));input.Connect("drag_cancelled",Callable.From(()=>{if(before.Count>0){_bones.restore(model,before);before=new Settings();}}));input.ValueChanged+=value=>{if(!owner.Get("_syncing").AsBool())_bones.commit(model,_bones.capture(model,actor),selected,new Settings{[channel]=Changed(value)},false);};owner.Get("_updaters").AsGodotArray().Add(Callable.From(()=>input.SetValueNoSignal(_bones.value(actor,selected,channel)[axis])));}}var key=new Button{Text="◆ Key selected bone pose · I",Name="KeyBonePose"};panel.AddChild(key);key.Pressed+=()=>_bones.key_pose(model,actor,selected);
    }
    public Button font_editor(Control owner,Control parent,string value,Variant callback)=>FontEditor(owner,parent,value,family=>Invoke(owner,callback,family));
    private Button FontEditor(Control owner,Control parent,string value,Action<string> commit)
    {
        var row=new HBoxContainer();parent.AddChild(row);var button=new Button{Name="SystemFontPicker",Text=value,Alignment=HorizontalAlignment.Left,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};button.AddThemeFontOverride("font",_textSettings.font(new Settings{[new StringName("font")]=value}));row.AddChild(button);var reset=new Button{Name="font_reset",Text="↺",TooltipText="Reset font",Visible=value!="Arial"};row.AddChild(reset);void Change(string family){button.Text=family;button.AddThemeFontOverride("font",_textSettings.font(new Settings{[new StringName("font")]=family}));reset.Visible=family!="Arial";commit(family);}reset.Pressed+=()=>Change("Arial");owner.Get("_updaters").AsGodotArray().Add(Callable.From(()=>reset.Visible=button.Text!="Arial"));button.Pressed+=()=>{var popup=new ActorFontPicker();button.AddChild(popup);var actor=owner.Get("_actor").As<Resource>();if(actor!=null)popup.Set("preview_text",_data.get_value(actor,"text","").ToString());_fonts.setup(popup,button.Text);popup.Connect("font_chosen",Callable.From<string>(Change));popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(470,460));popup.Get("search").As<Control>().GrabFocus();};return button;
    }
}
